// High-contrast styling for the tab container
element.style.backgroundColor = '#0f4c81';
element.style.borderRadius = '6px 6px 0 0';
element.style.border = '2px solid #ff9900';
element.style.borderBottom = 'none';
element.style.boxShadow = '0 -2px 8px rgba(255, 153, 0, 0.45)';
element.style.padding = '0 10px';
element.style.transition = 'background-color 0.2s';

// Style the inner anchor link
const anchor = element.querySelector('a');
if (anchor) {
  anchor.style.color = '#ffffff';
  anchor.style.fontWeight = '700';
  anchor.style.fontSize = '15px';
  anchor.style.letterSpacing = '0.3px';
  anchor.style.display = 'flex';
  anchor.style.alignItems = 'center';
  anchor.style.gap = '7px';
  anchor.style.textDecoration = 'none';
  anchor.style.padding = '8px 4px';

  // Inject SVG icon only once (idempotent guard)
  if (!anchor.querySelector('.friends-tab-icon')) {
    const svgNS = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(svgNS, 'svg');
    svg.setAttribute('class', 'friends-tab-icon');
    svg.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
    svg.setAttribute('viewBox', '0 0 24 24');
    svg.setAttribute('width', '18');
    svg.setAttribute('height', '18');
    svg.setAttribute('fill', '#ff9900');
    svg.setAttribute('aria-hidden', 'true');
    svg.style.flexShrink = '0';

    // Person 1 (back-left)
    const circle1 = document.createElementNS(svgNS, 'circle');
    circle1.setAttribute('cx', '8');
    circle1.setAttribute('cy', '7');
    circle1.setAttribute('r', '3');
    circle1.setAttribute('opacity', '0.75');

    const path1 = document.createElementNS(svgNS, 'path');
    path1.setAttribute('d', 'M2 20c0-3.314 2.686-6 6-6s6 2.686 6 6');
    path1.setAttribute('opacity', '0.75');

    // Person 2 (front-right)
    const circle2 = document.createElementNS(svgNS, 'circle');
    circle2.setAttribute('cx', '16');
    circle2.setAttribute('cy', '7');
    circle2.setAttribute('r', '3');

    const path2 = document.createElementNS(svgNS, 'path');
    path2.setAttribute('d', 'M10 20c0-3.314 2.686-6 6-6s6 2.686 6 6');

    svg.appendChild(circle1);
    svg.appendChild(path1);
    svg.appendChild(circle2);
    svg.appendChild(path2);

    anchor.insertBefore(svg, anchor.firstChild);
  }
}
